UPDATE moulds AS mould
SET manufacturer = source.manufacturer,
    keeper = NULL,
    updated_at = clock_timestamp()
FROM source_rows AS source
WHERE mould.legacy_id = source.legacy_id
  AND mould.is_deleted = false
  AND NULLIF(btrim(mould.manufacturer), '') IS NULL
  AND mould.keeper_id IS NULL
  AND mould.keeper = source.manufacturer;

COMMENT ON COLUMN moulds.manufacturer IS
    '模具制造商/模具供应商原文；旧 B_Mould.summary 经 2026-10-31 业务确认映射，不自动绑定供应商 UUID';
COMMENT ON COLUMN moulds.keeper IS
    '保管人文本；与 keeper_id 配套。旧 B_Mould.summary 为制造商，不能当作保管人导入';
